var loginUserService = async (c4, email, password) => {
  const dbInstance = c4.get("db");
  try {
    const [user] = await dbInstance.select().from(Users).where(eq(Users.email, email)).limit(1);
    if (!user) {
      console.log(`Login attempt failed: User not found for email ${email}`);
      return err({ type: "invalid_credentials" });
    }
    if (!user.passwordHash) {
      console.error(`Login attempt failed: User ${email} has no password hash set.`);
      return err({ type: "no_password_hash" });
    }
    const passwordIsValid = await compare(password, user.passwordHash);
    if (!passwordIsValid) {
      console.log(`Login attempt failed: Invalid password for user ${email}`);
      return err({ type: "invalid_credentials" });
    }
    const now = Math.floor(Date.now() / 1e3);
    const payload = {
      iss: JWT_ISSUER,
      aud: JWT_AUDIENCE,
      sub: user.id.toString(),
      iat: now,
      exp: now + JWT_EXPIRY_SECONDS
    };
    let token;
    try {
      token = await sign2(payload, JWT_SECRET);
    } catch (jwtError) {
      console.error("JWT signing error:", jwtError);
      return err({ type: "jwt_signing_error" });
    }
    return ok({
      id: user.id,
      token,
      role: user.role,
      name: user.nome,
      user: {
        id: user.id,
        nome: user.nome,
        email: user.email,
        role: user.role,
        school: user.school,
        matricula: user.matricula,
        academicTitle: user.academicTitle,
        updatedAt: user.updatedAt
      }
    });
  } catch (dbError) {
    console.error("Database error during login:", dbError);
    return err({ type: "database_error" });
  }
};
