var getUpcomingBancasVisible = async (c4, orderBy, order, page = 1, limit = 10, searchQuery) => {
  try {
    const dao = new BancaDAO(c4.get);
    const userId = c4.get("jwtPayload")?.sub;
    const user = await getUserById(c4, Number(userId));
    const userRole2 = user.ok ? user.data.role : void 0;
    const { bancas, total } = await dao.getUpcomingBancas({
      page,
      limit,
      orderBy,
      order,
      searchQuery,
      userId: userId ? Number(userId) : void 0,
      userRole: userRole2
    });
    const totalPages = Math.ceil(total / limit);
    return ok({
      bancasWithMembros: bancas,
      meta: {
        total,
        totalPages,
        currentPage: page,
        limit,
        hasNext: page < totalPages,
        hasPrev: page > 1
      }
    });
  } catch (error) {
    console.error("Error fetching upcoming bancas:", error);
    return err({ type: "database_error", error });
  }
};
