var toggleBancaVisibility = async (c4, bancaId) => {
  const db3 = c4.get("db");
  const payload = c4.get("jwtPayload");
  try {
    const [banca] = await db3.select().from(Bancas).where(eq(Bancas.id, bancaId));
    if (!banca) {
      return err({ type: "banca_not_found" });
    }
    const userResult = await getUserById(c4, Number(payload.sub));
    if (!userResult.ok) {
      return err({ type: "unauthorized" });
    }
    const user = userResult.data;
    if (user.role !== "ADMIN" && banca.orientadorId !== user.id) {
      return err({ type: "unauthorized" });
    }
    const newVisibility = !banca.visible;
    const [updatedBanca] = await db3.update(Bancas).set({ visible: newVisibility }).where(eq(Bancas.id, bancaId)).returning();
    return ok(updatedBanca);
  } catch (error) {
    console.error(`Error toggling visibility for banca ID ${bancaId}:`, error);
    return err({ type: "database_error", error });
  }
};
