var setEvaluatorGrade = async (c4, bancaId, userId, grade, currentUserId) => {
  const dbInstance = c4.get("db");
  try {
    const relationExists = await dbInstance.select({ id: usuariosBancas.id }).from(usuariosBancas).where(and(eq(usuariosBancas.usuarioId, userId), eq(usuariosBancas.bancaId, bancaId))).limit(1);
    if (relationExists.length === 0) {
      return err({ type: "relation_not_found" });
    }
    const currentUserResult = await getUserById(c4, currentUserId);
    if (!currentUserResult.ok) {
      return err({ type: "database_error", error: "User not found" });
    }
    const isAdmin = currentUserResult.data.role === "ADMIN";
    const isOwnGrade = currentUserId === userId;
    const banca = await dbInstance.query.Bancas.findFirst({
      where: eq(Bancas.id, bancaId),
      columns: { orientadorId: true }
    });
    const isOrientadorDaBanca = banca?.orientadorId === currentUserId;
    if (!isAdmin && !isOwnGrade && !isOrientadorDaBanca) {
      return err({ type: "unauthorized" });
    }
    const [updatedRelation] = await dbInstance.update(usuariosBancas).set({ nota: grade }).where(and(eq(usuariosBancas.usuarioId, userId), eq(usuariosBancas.bancaId, bancaId))).returning();
    return ok(updatedRelation);
  } catch (error) {
    console.error(`Error setting grade for user ${userId} in banca ${bancaId}:`, error);
    return err({ type: "database_error", error });
  }
};
