// src/services/calendar.service.ts
var generateICSContent = (data2) => {
  const { banca } = data2;
  const startDate = new Date(banca.dataRealizacao);
  const endDate = new Date(startDate.getTime() + 2 * 60 * 60 * 1e3);
  const formatDateForICS = (date2) => {
    return date2.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
  };
  const startFormatted = formatDateForICS(startDate);
  const endFormatted = formatDateForICS(endDate);
  const description = [
    `T\xEDtulo: ${banca.tituloTrabalho}`,
    `Autor: ${banca.autor}`,
    banca.orientador ? `Orientador: ${banca.orientador.nome}` : "",
    banca.curso ? `Curso: ${banca.curso.nome}` : "",
    `Per\xEDodo: ${banca.periodoAcademico}`,
    banca.turma ? `Turma: ${banca.turma}` : "",
    "",
    banca.resumo ? `Resumo: ${banca.resumo.substring(0, 200)}...` : ""
  ].filter(Boolean).join("\\n");
  const uid = `banca-${banca.id}-${Date.now()}@sisdef.ufba.br`;
  const icsContent = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//UFBA//SISDEF//PT",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    `UID:${uid}`,
    `DTSTART:${startFormatted}`,
    `DTEND:${endFormatted}`,
    `SUMMARY:Defesa de TCC - ${banca.autor}`,
    `DESCRIPTION:${description}`,
    banca.local ? `LOCATION:${banca.local}` : "",
    "ORGANIZER:mailto:noreply@sisdef.ufba.br",
    "STATUS:CONFIRMED",
    "CLASS:PUBLIC",
    `CREATED:${formatDateForICS(/* @__PURE__ */ new Date())}`,
    `LAST-MODIFIED:${formatDateForICS(/* @__PURE__ */ new Date())}`,
    "END:VEVENT",
    "END:VCALENDAR"
  ].filter(Boolean).join("\r\n");
  return icsContent;
};
var generateGoogleCalendarUrl = (data2) => {
  const { banca } = data2;
  const startDate = new Date(banca.dataRealizacao);
  const endDate = new Date(startDate.getTime() + 2 * 60 * 60 * 1e3);
  const formatDateForGoogle = (date2) => {
    return date2.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
  };
  const startFormatted = formatDateForGoogle(startDate);
  const endFormatted = formatDateForGoogle(endDate);
  const title = `Defesa de TCC - ${banca.autor}`;
  const details = [
    `T\xEDtulo: ${banca.tituloTrabalho}`,
    `Autor: ${banca.autor}`,
    banca.orientador ? `Orientador: ${banca.orientador.nome}` : "",
    banca.curso ? `Curso: ${banca.curso.nome}` : "",
    `Per\xEDodo: ${banca.periodoAcademico}`,
    banca.turma ? `Turma: ${banca.turma}` : ""
  ].filter(Boolean).join("\n");
  const location = banca.local || "";
  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: title,
    dates: `${startFormatted}/${endFormatted}`,
    details,
    location,
    trp: "false"
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
};
var generateOutlookUrl = (data2) => {
  const { banca } = data2;
  const startDate = new Date(banca.dataRealizacao);
  const endDate = new Date(startDate.getTime() + 2 * 60 * 60 * 1e3);
  const startFormatted = startDate.toISOString();
  const endFormatted = endDate.toISOString();
  const subject = `Defesa de TCC - ${banca.autor}`;
  const body = [
    `T\xEDtulo: ${banca.tituloTrabalho}`,
    `Autor: ${banca.autor}`,
    banca.orientador ? `Orientador: ${banca.orientador.nome}` : "",
    banca.curso ? `Curso: ${banca.curso.nome}` : "",
    `Per\xEDodo: ${banca.periodoAcademico}`,
    banca.turma ? `Turma: ${banca.turma}` : "",
    "",
    banca.resumo ? `Resumo: ${banca.resumo.substring(0, 200)}...` : ""
  ].filter(Boolean).join("\n");
  const location = banca.local || "";
  const params = new URLSearchParams({
    subject,
    body,
    startdt: startFormatted,
    enddt: endFormatted,
    location
  });
  return `https://outlook.live.com/calendar/0/deeplink/compose?${params.toString()}`;
};
var generateCalendarInvites = (data2) => {
  return {
    ics: generateICSContent(data2),
    googleUrl: generateGoogleCalendarUrl(data2),
    outlookUrl: generateOutlookUrl(data2)
  };
};

