var getBancaInfoForDocument = async (c4, bancaId) => {
  const dbInstance = c4.get("db");
  try {
    const bancaInfo = await dbInstance.query.Bancas.findFirst({
      with: {
        orientador: true,
        curso: true,
        membros: {
          with: {
            usuario: true
          }
        }
      },
      where: eq(Bancas.id, bancaId)
    });
    if (!bancaInfo) {
      return err({ type: "banca_not_found" });
    }
    return ok(bancaInfo);
  } catch (error) {
    console.error("Error fetching banca info:", error);
    return err({ type: "database_error", error });
  }
};

