// src/modules/feedback/feedback.service.ts
var createFeedback = async (c4, data2) => {
  const dbInstance = c4.get("db");
  const userId = c4.get("jwtPayload").sub;
  try {
    const [existingFeedback] = await dbInstance.select({ id: feedbackSubmissions.id }).from(feedbackSubmissions).where(eq(feedbackSubmissions.userId, userId)).limit(1);
    if (existingFeedback) {
      return err({ type: "duplicate_feedback" });
    }
    const [newFeedback] = await dbInstance.insert(feedbackSubmissions).values({
      userId,
      taskComplexityRating: data2.taskComplexityRating,
      interfaceConsistencyRating: data2.interfaceConsistencyRating,
      responseTimeRating: data2.responseTimeRating,
      satisfactionRating: data2.satisfactionRating,
      usagePurposes: JSON.stringify(data2.usagePurposes),
      usagePurposeOther: data2.usagePurposeOther,
      completedAllTasks: data2.completedAllTasks
    }).returning({ id: feedbackSubmissions.id });
    if (!newFeedback) {
      console.error("Failed to insert feedback submission");
      return err({ type: "database_error", error: "Insert operation did not return expected data." });
    }
    return ok({ id: newFeedback.id });
  } catch (error) {
    console.error("Error creating feedback submission:", error);
    return err({ type: "database_error", error });
  }
};
var getFeedbackStatistics = async (c4) => {
  const dbInstance = c4.get("db");
  try {
    const [statistics] = await dbInstance.select({
      totalSubmissions: count(),
      averageTaskComplexity: avg(feedbackSubmissions.taskComplexityRating),
      averageInterfaceConsistency: avg(feedbackSubmissions.interfaceConsistencyRating),
      averageResponseTime: avg(feedbackSubmissions.responseTimeRating),
      averageSatisfaction: avg(feedbackSubmissions.satisfactionRating),
      completedAllTasksCount: sql`SUM(CASE WHEN ${feedbackSubmissions.completedAllTasks} = true THEN 1 ELSE 0 END)`,
      notCompletedAllTasksCount: sql`SUM(CASE WHEN ${feedbackSubmissions.completedAllTasks} = false THEN 1 ELSE 0 END)`,
      studentSubmissions: sql`SUM(CASE WHEN ${Users.role} = 'STUDENT' THEN 1 ELSE 0 END)`,
      teacherSubmissions: sql`SUM(CASE WHEN ${Users.role} = 'TEACHER' OR ${Users.role} = 'ADMIN' THEN 1 ELSE 0 END)`
    }).from(feedbackSubmissions).leftJoin(Users, eq(feedbackSubmissions.userId, Users.id));
    if (!statistics) {
      return ok({
        totalSubmissions: 0,
        averageTaskComplexity: 0,
        averageInterfaceConsistency: 0,
        averageResponseTime: 0,
        averageSatisfaction: 0,
        completedAllTasksCount: 0,
        notCompletedAllTasksCount: 0,
        studentSubmissions: 0,
        teacherSubmissions: 0
      });
    }
    return ok({
      totalSubmissions: Number(statistics.totalSubmissions),
      averageTaskComplexity: Number(statistics.averageTaskComplexity) || 0,
      averageInterfaceConsistency: Number(statistics.averageInterfaceConsistency) || 0,
      averageResponseTime: Number(statistics.averageResponseTime) || 0,
      averageSatisfaction: Number(statistics.averageSatisfaction) || 0,
      completedAllTasksCount: Number(statistics.completedAllTasksCount),
      notCompletedAllTasksCount: Number(statistics.notCompletedAllTasksCount),
      studentSubmissions: Number(statistics.studentSubmissions),
      teacherSubmissions: Number(statistics.teacherSubmissions)
    });
  } catch (error) {
    console.error("Error fetching feedback statistics:", error);
    return err({ type: "database_error", error });
  }
};

