var createFeatureRequestSchema = z.object({
  title: z.string().min(1, { message: "T\xEDtulo \xE9 obrigat\xF3rio." }).max(200, { message: "T\xEDtulo muito longo." }),
  description: z.string().min(1, { message: "Descri\xE7\xE3o \xE9 obrigat\xF3ria." })
});
var voteFeatureRequestSchema = z.object({
  featureRequestId: z.number().int().positive({ message: "ID da solicita\xE7\xE3o \xE9 obrigat\xF3rio." })
});

// src/modules/feature-request/feature-request.service.ts
var createFeatureRequest = async (c4, data2) => {
  const dbInstance = c4.get("db");
  const userId = c4.get("jwtPayload").sub;
  try {
    const [newFeatureRequest] = await dbInstance.insert(featureRequests).values({
      userId,
      title: data2.title,
      description: data2.description,
      voteCount: 0
    }).returning({ id: featureRequests.id });
    if (!newFeatureRequest) {
      console.error("Failed to insert feature request");
      return err({ type: "database_error", error: "Insert operation did not return expected data." });
    }
    return ok({ id: newFeatureRequest.id });
  } catch (error) {
    console.error("Error creating feature request:", error);
    return err({ type: "database_error", error });
  }
};
var getAllFeatureRequests = async (c4) => {
  const dbInstance = c4.get("db");
  try {
    const requests = await dbInstance.select({
      id: featureRequests.id,
      title: featureRequests.title,
      description: featureRequests.description,
      voteCount: featureRequests.voteCount,
      createdAt: featureRequests.createdAt,
      authorName: Users.nome,
      authorId: Users.id
    }).from(featureRequests).innerJoin(Users, eq(featureRequests.userId, Users.id)).orderBy(desc(featureRequests.voteCount), desc(featureRequests.createdAt));
    return ok(requests);
  } catch (error) {
    console.error("Error fetching feature requests:", error);
    return err({ type: "database_error", error });
  }
};
var voteFeatureRequest = async (c4, userId, featureRequestId) => {
  const dbInstance = c4.get("db");
  try {
    const [featureRequest] = await dbInstance.select({ id: featureRequests.id }).from(featureRequests).where(eq(featureRequests.id, featureRequestId)).limit(1);
    if (!featureRequest) {
      return err({ type: "not_found" });
    }
    const existingVote = await dbInstance.select({ id: featureRequestVotes.id }).from(featureRequestVotes).where(
      sql`${featureRequestVotes.userId} = ${userId} AND ${featureRequestVotes.featureRequestId} = ${featureRequestId}`
    ).limit(1);
    if (existingVote.length > 0) {
      return err({ type: "duplicate_vote" });
    }
    await dbInstance.transaction(async (tx) => {
      await tx.insert(featureRequestVotes).values({
        userId,
        featureRequestId
      });
      await tx.update(featureRequests).set({
        voteCount: sql`${featureRequests.voteCount} + 1`
      }).where(eq(featureRequests.id, featureRequestId));
    });
    const [updatedRequest] = await dbInstance.select({ voteCount: featureRequests.voteCount }).from(featureRequests).where(eq(featureRequests.id, featureRequestId)).limit(1);
    return ok({ voteCount: updatedRequest?.voteCount ?? 0 });
  } catch (error) {
    console.error("Error voting on feature request:", error);
    return err({ type: "database_error", error });
  }
};
var checkIfUserVoted = async (c4, userId, featureRequestId) => {
  const dbInstance = c4.get("db");
  try {
    const existingVote = await dbInstance.select({ id: featureRequestVotes.id }).from(featureRequestVotes).where(
      sql`${featureRequestVotes.userId} = ${userId} AND ${featureRequestVotes.featureRequestId} = ${featureRequestId}`
    ).limit(1);
    return ok(existingVote.length > 0);
  } catch (error) {
    console.error("Error checking if user voted:", error);
    return err({ type: "database_error", error });
  }
};

