var updateCandidatoMestrado = async (c4, id, body) => {
  const dbInstance = c4.get("db");
  try {
    const [candidatoAtualizado] = await dbInstance.update(CandidatoMestrado).set(body).where(eq(CandidatoMestrado.id, Number(id))).returning();
    if (!candidatoAtualizado) return ok(null);
    const [enderecoAtual] = await dbInstance.select().from(Endereco).where(eq(Endereco.id, candidatoAtualizado.idEndereco));
    return ok({ ...candidatoAtualizado, endereco: enderecoAtual ?? null });
  } catch (error) {
    console.error(`Error updating mestrado candidato with ID ${id}:`, error);
    return err({ type: "database_error", error });
  }
};
var updateNotaMestrado = async (c4, idCandidato, body) => {
  const dbInstance = c4.get("db");
  try {
    const [notaAtualizada] = await dbInstance.insert(NotaMestrado).values({
      idCandidato: Number(idCandidato),
      ...body
    }).onConflictDoUpdate({
      target: NotaMestrado.idCandidato,
      // Assumindo que idCandidato é UNIQUE
      set: body
    }).returning();
    return ok(notaAtualizada ?? null);
  } catch (error) {
    console.error(
      `Error updating/inserting nota mestrado for candidato ID ${idCandidato}:`,
      error
    );
    return err({ type: "database_error", error });
  }
};
